import{_ as e,o as a,c as d,a2 as i}from"./chunks/framework.XctAhZuT.js";const r="/docs/images/guide/review-queue.svg",p=JSON.parse('{"title":"复习系统","description":"复习系统负责从本地状态中选择到期项目、提交评分、更新记忆状态并记录历史。它不负责定义课程内容。","frontmatter":{"description":"复习系统负责从本地状态中选择到期项目、提交评分、更新记忆状态并记录历史。它不负责定义课程内容。"},"headers":[],"relativePath":"guide/review-system.md","filePath":"guide/review-system.md","lastUpdated":1789373514000}'),l={name:"guide/review-system.md"};function o(s,t,n,h,c,u){return a(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="复习系统" tabindex="-1">复习系统 <a class="header-anchor" href="#复习系统" aria-label="Permalink to &quot;复习系统&quot;">​</a></h1><p>复习系统负责从本地状态中选择到期项目、提交评分、更新记忆状态并记录历史。它不负责定义课程内容。</p><h2 id="项目来源" tabindex="-1">项目来源 <a class="header-anchor" href="#项目来源" aria-label="Permalink to &quot;项目来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>调度所有者</th><th>说明</th></tr></thead><tbody><tr><td>课程词汇、表达、语法</td><td>Turna FSRS</td><td>使用 Dart <code>FsrsEngine</code></td></tr><tr><td>Official Anki 卡片</td><td>Official Anki scheduler</td><td>使用 rslib FFI 会话</td></tr><tr><td>错题专项</td><td>错题与课程状态</td><td>可重新组装练习，不替代正式 SRS</td></tr><tr><td>弱词专项</td><td>SRS 与学习证据</td><td>选择稳定度低或近期失败项目</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">所有者边界</p><p>不同所有者不得在运行时混写同一张卡片的调度状态。Official owner 不可用时应关闭相关复习，而不是静默改用 Turna FSRS。</p></div><h2 id="队列生命周期" tabindex="-1">队列生命周期 <a class="header-anchor" href="#队列生命周期" aria-label="Permalink to &quot;队列生命周期&quot;">​</a></h2><ol><li>读取当前时间与本地到期状态。</li><li>按来源和配置构造队列。</li><li>展示题目或卡片正面。</li><li>接收二元或四档评分。</li><li>调度器计算新状态和 due。</li><li>在事务边界内写入状态与历史。</li><li>从队列移除或按重学规则重新插入。</li></ol><p><img src="'+r+'" alt="复习队列生命周期：课程 FSRS 车道与 Official Anki 车道分离" loading="lazy"></p><h2 id="当日重学" tabindex="-1">当日重学 <a class="header-anchor" href="#当日重学" aria-label="Permalink to &quot;当日重学&quot;">​</a></h2><p>失败项目进入短间隔重学。默认短步进为 10 分钟。当日失败次数达到 <code>maxSameDayFails</code> 后，due 推迟到次日，避免在单日内无限循环同一项目。</p><h2 id="撤销" tabindex="-1">撤销 <a class="header-anchor" href="#撤销" aria-label="Permalink to &quot;撤销&quot;">​</a></h2><p>撤销依赖上一条复习历史和评分前状态。评分写入期间，该项目处于 in-flight 状态，不接受并发撤销。写入完成后才允许恢复。</p><h2 id="同胞卡" tabindex="-1">同胞卡 <a class="header-anchor" href="#同胞卡" aria-label="Permalink to &quot;同胞卡&quot;">​</a></h2><p>Anki 同一 note 生成的多张 card 可按 <code>importId + noteId</code> 归组。复习中可对卡片执行 bury / suspend 操作（<code>BURY_OR_SUSPEND_CARDS</code> 契约），这是用户手动动作，不是自动埋藏开关 —— 当前没有「同日新卡 / 复习卡自动隐藏」的设置项。</p><h2 id="难卡" tabindex="-1">难卡 <a class="header-anchor" href="#难卡" aria-label="Permalink to &quot;难卡&quot;">​</a></h2><p>难卡（leech）判定是固定规则：<code>lapses &gt;= 5 且 lapses &gt; reps</code>（<code>fsrs_engine.dart</code>），不可配置。leech 在到期队列中被降权排到末尾，并计入记忆曲线的独立成熟度桶 —— 当前没有自动暂停和难卡专项视图。</p><h2 id="队列异常" tabindex="-1">队列异常 <a class="header-anchor" href="#队列异常" aria-label="Permalink to &quot;队列异常&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>检查</th></tr></thead><tbody><tr><td>今日无卡</td><td>检查系统时间、目标课程、due 与筛选规则</td></tr><tr><td>同一卡重复出现</td><td>检查重学阶梯和提交事务是否成功</td></tr><tr><td>Anki 评分不更新</td><td>检查 Official runtime 与 owner</td></tr><tr><td>撤销不可用</td><td>等待在途评分完成，检查历史是否存在</td></tr><tr><td>新卡过多</td><td>调整新卡顺序、上限或同胞卡规则</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/fsrs">FSRS 复习</a></li><li><a href="/docs/guide/memory-state">记忆状态与评分</a></li><li><a href="/docs/guide/mistakes-and-weak-items">错题与弱项</a></li></ul>',20)])])}const f=e(l,[["render",o]]);export{p as __pageData,f as default};
